    /// <summary>
    /// Modify based on the user selected InventLocation
    /// </summary>
    /// <param name="sender">Form datasource</param>
    /// <param name="e">Data field</param>
    [FormDataFieldEventHandler(formDataFieldStr(InventJournalCount, InventDim, InventLocationId), FormDataFieldEventType::Modified), 
        FormDataFieldEventHandler(formDataFieldStr(InventJournalLossProfit, InventDim, InventLocationId), FormDataFieldEventType::Modified),
        FormDataFieldEventHandler(formDataFieldStr(InventJournalMovement, InventDim, InventLocationId), FormDataFieldEventType::Modified),
        FormDataFieldEventHandler(formDataFieldStr(InventJournalTransfer, InventDimIssue, InventLocationId), FormDataFieldEventType::Modified),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void InventJournalsInventLocationId_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
    {
        FormRun         fr          = sender.datasource().formRun();
        InventDim       inventDim   = sender.datasource().cursor();
        str             callername  = fr.form().name(); 
        FormDataSource  inventJournalTrans_ds;

        if (callername == formStr(InventJournalCount))
        {
            inventJournalTrans_ds   = fr.dataSource(formDataSourceStr(InventJournalCount, InventJournalTrans));
        }
        else if (callername == formStr(InventJournalLossProfit))
        {
            inventJournalTrans_ds   = fr.dataSource(formDataSourceStr(InventJournalLossProfit, InventJournalTrans));
        }
        else if (callername == formStr(InventJournalMovement))
        {
            inventJournalTrans_ds   = fr.dataSource(formDataSourceStr(InventJournalMovement, InventJournalTrans));
        }
        else if (callername == formStr(InventJournalTransfer))
        {
            inventJournalTrans_ds   = fr.dataSource(formDataSourceStr(InventJournalTransfer, InventJournalTrans));
        }
        if (Callername)
        {
            InventJournalTrans  inventJournalTrans      = inventJournalTrans_ds.cursor();

            if (inventDim.InventLocationId)
            {
                inventJournalTrans.DefaultDimension = InventLocation::changeDimension(inventJournalTrans.DefaultDimension, inventDim.InventLocationId);
            }

            DimensionDisplayValue dimensionValue = METInventJournalEventHandler::getDimensionDisplayValue(inventJournalTrans.DefaultDimension, METConstants::profitCentre);
            if(!dimensionValue || !inventDim.InventLocationId)
            {
                inventJournalTrans.DefaultDimension = InventSite::changeDimension(inventJournalTrans.DefaultDimension, InventSite::find(inventDim.InventSiteId).SiteId);
            }
            
        }
        
    }

    /// <summary>
    /// Find the last unit conversion value
    /// </summary>
    /// <param name="_itemId">Item Id value</param>
    /// <param name="_tounitconversion">To unit conversion</param>
    public UnitOfMeasureConversion finalUnitConvsersion(ItemId _itemId, RecId _tounitconversion)
    {
        UnitOfMeasure           allToUnitOfMeasure;
        EcoResProduct           ecoProduct;
        UnitOfMeasureConversion unitOfMeasureConversion;
        InventTableModule       inventModule;
        
        // To get the last unit conversion value
        select unitOfMeasureConversion where unitOfMeasureConversion.FromUnitOfMeasure == _tounitconversion
                        join allToUnitOfMeasure where unitOfMeasureConversion.ToUnitOfMeasure == allToUnitOfMeasure.RecId
                        join ecoProduct where ecoProduct.recid == unitOfMeasureConversion.Product 
                        join inventModule where inventModule.ItemId == ecoProduct.DisplayProductNumber &&
                        inventModule.ModuleType == ModuleInventPurchSales::Invent &&
                        ecoProduct.DisplayProductNumber == _itemId;

        // To avoid infinite loop
        if (unitOfMeasureConversion.RecId !=0)
        {
            if (allToUnitOfMeasure.Symbol  == inventModule.UnitId)
            {  
                return unitOfMeasureConversion;
            }
            else
            {
                this.finalUnitConvsersion(_itemId,unitOfMeasureConversion.ToUnitOfMeasure);
            }
        }
        
        return unitOfMeasureConversion;

    }

    /// <summary>
    /// On update the value of qty, update the value of duty and total duty
    /// </summary>
    /// <param name="sender">Pass the value</param>
    /// <param name="e">Data event value</param>
    [DataEventHandler(tableStr(InventJournalTrans), DataEventType::Updated)]
    public static void InventJournalTrans_onUpdated(Common sender, DataEventArgs e)
    {
        InventJournalTrans      inventJournalTrans = sender as InventJournalTrans;
        METinventtable          inventTable;
        METTariffItemCodeBase   dutyItemCode;
        METExciseSiteDutySetup  exciseSiteDutySetup;
        UnitOfMeasureConversion unitOfMeasureConversion,finalUnitConversion;
        UnitOfMeasure           allFromUnitOfMeasure;
        EcoResProduct           ecoProduct;
        #define.CA('CA')
        
        METInventJournalEventHandler unitconversion = new METInventJournalEventHandler();
        
        // To find the Container unit value for the item first level
        select firstonly unitOfMeasureConversion
                join allFromUnitOfMeasure where unitOfMeasureConversion.FromUnitOfMeasure == allFromUnitOfMeasure.RecId
                join ecoProduct where ecoProduct.recid == unitOfMeasureConversion.Product &&
                ecoProduct.DisplayProductNumber == inventJournalTrans.ItemId &&
                allFromUnitOfMeasure.Symbol == #CA;

       
        finalUnitConversion  = unitconversion.finalUnitConvsersion(inventJournalTrans.ItemId,unitOfMeasureConversion.ToUnitOfMeasure);
        
        // TO find the Customexcise value
        select firstonly inventTable join dutyItemCode
                where dutyItemCode.RecId == inventTable.METTariffItemCodeBaseRecid
                 join exciseSiteDutySetup where exciseSiteDutySetup.ItemId == inventTable.ItemId &&
                    inventTable.ItemId == inventJournalTrans.ItemId;

        // Few items qty and some are cwqty
        real dutyQty = inventJournalTrans.Qty != 0.000000 ? inventJournalTrans.Qty : inventJournalTrans.PdsCWQty;

        if (dutyItemCode.CustomsExcise)
        {
            inventJournalTrans.METValueForDuty  = exciseSiteDutySetup.DutyTotal/finalUnitConversion.Factor;
            inventJournalTrans.METDutyTotal     = dutyQty * inventJournalTrans.METValueForDuty;
        }
    }

    /// <summary>
    /// On insert update the value of duty and total value
    /// </summary>
    /// <param name="sender">Pass the value</param>
    /// <param name="e">Data event value</param>
    [DataEventHandler(tableStr(InventJournalTrans), DataEventType::Inserted)]
    public static void InventJournalTrans_onInserted(Common sender, DataEventArgs e)
    {
        InventJournalTrans      inventJournalTrans = sender as InventJournalTrans;
        METinventtable          inventTable;
        METTariffItemCodeBase   dutyItemCode;
        METExciseSiteDutySetup  exciseSiteDutySetup;
        UnitOfMeasureConversion unitOfMeasureConversion,finalUnitConversion;
        UnitOfMeasure           allFromUnitOfMeasure;
        EcoResProduct           ecoProduct;
        #define.CA('CA')
        
        METInventJournalEventHandler unitconversion = new METInventJournalEventHandler();
        
        // To find the Container unit value for the item first level
        select firstonly unitOfMeasureConversion  
                join allFromUnitOfMeasure where unitOfMeasureConversion.FromUnitOfMeasure == allFromUnitOfMeasure.RecId
                join ecoProduct where ecoProduct.recid == unitOfMeasureConversion.Product &&
                ecoProduct.DisplayProductNumber == inventJournalTrans.ItemId &&
                allFromUnitOfMeasure.Symbol == #CA;

       
        finalUnitConversion  = unitconversion.finalUnitConvsersion(inventJournalTrans.ItemId,unitOfMeasureConversion.ToUnitOfMeasure);
        
        // TO find the Customexcise value
        select firstonly inventTable join dutyItemCode
                where dutyItemCode.RecId == inventTable.METTariffItemCodeBaseRecid
                 join exciseSiteDutySetup where exciseSiteDutySetup.ItemId == inventTable.ItemId &&
                    inventTable.ItemId == inventJournalTrans.ItemId;

        // Few items qty and some are cwqty
        real dutyQty = inventJournalTrans.Qty != 0.000000 ? inventJournalTrans.Qty : inventJournalTrans.PdsCWQty;

        if (dutyItemCode.CustomsExcise)
        {
            inventJournalTrans.METValueForDuty  = exciseSiteDutySetup.DutyTotal/finalUnitConversion.Factor; 
            inventJournalTrans.METDutyTotal     = dutyQty * inventJournalTrans.METValueForDuty;
        }
       
    }

    /// <summary>
    /// Modify based on the user selected InventSite
    /// </summary>
    /// <param name="sender">Form datasource</param>
    /// <param name="e">Data field</param>
    [FormDataFieldEventHandler(formDataFieldStr(InventJournalCount, InventDim, InventSiteId), FormDataFieldEventType::Modified),
        FormDataFieldEventHandler(formDataFieldStr(InventJournalLossProfit, InventDim, InventSiteId), FormDataFieldEventType::Modified),
        FormDataFieldEventHandler(formDataFieldStr(InventJournalMovement, InventDim, InventSiteId), FormDataFieldEventType::Modified),
        FormDataFieldEventHandler(formDataFieldStr(InventJournalTransfer, InventDimIssue, InventSiteId), FormDataFieldEventType::Modified),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void InventJournalsInventSiteId_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
    {
        FormRun             fr          = sender.datasource().formRun();
        InventDim           inventDim   = sender.datasource().cursor();
        str                 callername  = fr.form().name(); 
        FormDataSource      inventJournalTrans_ds;

        if (callername == formStr(InventJournalCount))
        {
            inventJournalTrans_ds   = fr.dataSource(formDataSourceStr(InventJournalCount, InventJournalTrans));
        }
        else if (callername == formStr(InventJournalLossProfit))
        {
            inventJournalTrans_ds   = fr.dataSource(formDataSourceStr(InventJournalLossProfit, InventJournalTrans));
        }
        else if (callername == formStr(InventJournalMovement))
        {
            inventJournalTrans_ds   = fr.dataSource(formDataSourceStr(InventJournalMovement, InventJournalTrans));
        }
        else if (callername == formStr(InventJournalTransfer))
        {
            inventJournalTrans_ds   = fr.dataSource(formDataSourceStr(InventJournalTransfer, InventJournalTrans));
        }
        if (Callername)
        {
            InventJournalTrans  inventJournalTrans      = inventJournalTrans_ds.cursor();
            inventJournalTrans.DefaultDimension = InventSite::changeDimension(inventJournalTrans.DefaultDimension, InventSite::find(inventDim.InventSiteId).SiteId);
        }
        
    }

/// <summary>
/// Get the DimensionDisplayValue
/// </summary>
/// <param name = "_defaultDimension">DefaultDimension</param>
/// <param name = "_dimName">DimensionName</param>
/// <returns>DisplayValue</returns>
public static DimensionDisplayValue getDimensionDisplayValue(RecId _defaultDimension, Name _dimName)
{
    DimensionAttributeValueSetStorage dimStorage;
    dimStorage = DimensionAttributeValueSetStorage::find(_defaultDimension);
    return dimStorage.getDisplayValueByDimensionAttribute(DimensionAttribute::findByName(_dimName).RecId);
}
